            artifact_type = t
            break
    if artifact_type is None:
        return None
    try:
        text = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return None
    meta = parse_frontmatter(text)
    name = str(meta.get("name", "")).strip() or stem
    tags = meta.get("tags", [])
    if not isinstance(tags, list):
        tags = []
    return {
